/* Explicit measured soffit sections and material insertions on the same physical walls. */
(function(root){'use strict';const copy=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),rect=(x,y,w,h)=>[[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
 function dialog(title,html,submit){const d=document.createElement('dialog');d.className='mir-level-dialog';d.innerHTML=`<h2>${title}</h2><form>${html}<p role="status"></p><button type="submit">${root.MIRLevelStudio.t('Voir l’aperçu')}</button><button type="button" data-cancel>${root.MIRLevelStudio.t('Annuler')}</button></form>`;document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>d.close();d.onclose=()=>d.remove();d.querySelector('form').onsubmit=e=>{e.preventDefault();try{submit(new FormData(e.target));d.close();}catch(error){d.querySelector('[role=status]').textContent=error.message;}};d.showModal();return d;}
 const field=(key,label,value='')=>`<label>${label}<input name="${key}" type="number" step="any" required value="${value}"></label>`;
 root.MIRStudioWallDetails={
 insertion({level,wall,materials,officialColor,stage}){
  const en=root.MIRClientLocale?.getLocale()==='en-CA',tr=(fr,eng)=>en?eng:fr,windows=(level.wallOpenings||[]).filter(o=>o.wallId===wall.id).sort((a,b)=>a.offset-b.offset),x=windows.length===2?windows[0].offset+windows[0].width:0,w=windows.length===2?windows[1].offset-x:'';
  dialog(tr('Insertion du mur','Wall insertion'),`<p>${tr('Les ouvertures restent distinctes. La surface d’insertion remplace la même surface de revêtement.','The openings remain separate. The insertion replaces the same siding area.')}</p>${field('x','X · m',x)}${field('y',tr('Depuis le haut · m','From top · m'),0)}${field('width',tr('Largeur · m','Width · m'),w)}${field('height',tr('Hauteur · m','Height · m'),wall.height)}<label>${tr('Produit','Product')}<select name="material">${materials.map(m=>`<option value="${esc(m.id)}">${esc(m.brand+' · '+m.name)}</option>`).join('')}</select></label><label>${tr('Sens de pose','Installation direction')}<select name="orientation"><option value="horizontal">Horizontal</option><option value="vertical">Vertical</option></select></label>`,form=>{const number=k=>Number(form.get(k)),x=number('x'),y=number('y'),w=number('width'),h=number('height'),material=materials.find(m=>m.id===form.get('material')),orientation=form.get('orientation');if(!(w>0&&h>0&&x>=0&&y>=0&&x+w<=wall.length+1e-6&&y+h<=wall.height+1e-6))throw Error(tr('L’insertion doit rester dans son mur.','The insertion must stay inside its wall.'));if(!material?.allowedOrientations?.includes(orientation))throw Error(tr('Ce sens de pose n’est pas documenté pour ce produit.','This installation direction is not documented for this product.'));const next=copy(level),id='insertion-'+crypto.randomUUID();next.wallZones=[...(next.wallZones||[]),{id,wallId:wall.id,kind:'siding',polygon:rect(x,y,w,h),selection:{materialId:material.id,pattern:material.renderPattern,orientation,...officialColor(material,{})},provenance:{kind:'user-created-insertion',wallId:wall.id,snap:windows.length===2?'between-two-openings':'manual'}}];stage(next);});
 },
 soffit({level,views,stage,materials,officialColor}){
  const en=root.MIRClientLocale?.getLocale()==='en-CA',tr=(fr,eng)=>en?eng:fr,rows=materials.filter(m=>m.applications?.includes('soffit'));
  dialog(tr('Section de soffite','Soffit section'),`<p>${tr('Relevez chaque section à sa hauteur. Les sections superposées restent distinctes. Aucune largeur de débord n’est supposée.','Measure each section at its height. Overlapping levels remain separate. No overhang width is assumed.')}</p>${field('x','X · m')}${field('y','Y · m')}${field('length',tr('Longueur du fascia · m','Fascia length · m'))}${field('depth',tr('Profondeur · m','Depth · m'))}${field('height',tr('Hauteur · m','Height · m'))}<label>${tr('Vue source','Source view')}<select name="source"><option value="">${tr('Mesure fournie','User measurement')}</option>${views.filter(v=>v.levelId==null||v.levelId===level.sourceLevel).map(v=>`<option value="${esc(v.id)}">p. ${v.page} · ${esc(v.payload.name)}</option>`).join('')}</select></label><label>${tr('Repère de la cote ou note','Dimension label or note')}<input name="label" required maxlength="240"></label><label>${tr('Produit','Product')}<select name="material"><option value="">${tr('À confirmer','To confirm')}</option>${rows.map(m=>`<option value="${esc(m.id)}">${esc(m.brand+' · '+m.name)}</option>`).join('')}</select></label>${[0,1,2,3].map(i=>`<label>${tr('Bord','Edge')} ${i+1}<select name="edge${i}"><option value="unknown">${tr('À confirmer','To confirm')}</option><option value="wall">${tr('Mur','Wall')}</option><option value="interior">${tr('Intérieur','Interior')}</option><option value="fascia">Fascia</option></select></label>`).join('')}<label><input type="checkbox" name="confirmed">${tr('Dimensions et hauteur vérifiées','Dimensions and height checked')}</label>`,form=>{const n=k=>Number(form.get(k)),x=n('x'),y=n('y'),length=n('length'),depth=n('depth'),height=n('height');if(!(length>0&&depth>0&&Number.isFinite(height)))throw Error(tr('Vérifiez les dimensions.','Check the dimensions.'));for(const s of level.soffits||[])if(Math.abs(s.height-height)<1e-6){const a=s.polygon?.[0];if(a&&Math.min(x+length,a[0]+s.length)>Math.max(x,a[0])+1e-6&&Math.min(y+depth,a[1]+s.depth)>Math.max(y,a[1])+1e-6)throw Error(tr('Deux sections se chevauchent à la même hauteur. Corrigez leur contour.','Two sections overlap at the same height. Correct their boundaries.'));}const m=rows.find(m=>m.id===form.get('material')),next=copy(level),sourceId=form.get('source');next.soffits=[...(next.soffits||[]),{id:'soffit-'+crypto.randomUUID(),polygon:rect(x,y,length,depth),length,depth,height,status:form.has('confirmed')?'confirmed':'proposed',edges:[length,depth,length,depth].map((length,i)=>({length,type:form.get('edge'+i)})),materialId:m?.id||null,...(m?officialColor(m,{}):{}),provenance:{kind:sourceId?'written':'user-measurement',sourceViewId:sourceId||null,label:form.get('label')}}];next.soffitsReviewed=false;stage(next);});
 }
 };
})(window);
